            script=new String(source.readAllBytes(),StandardCharsets.UTF_8).replaceAll("(?m)^\\s*--.*$","");
        } catch(Exception ignored) { throw new IllegalStateException("Native RAG migration resource unavailable"); }
        for(String sql:script.split(";")) {
